// ── FIRESTORE HELPERS (realtime sync across all devices) ──────────────────────
function subscribeCollection(name, setState){
  return onSnapshot(collection(db, name), (snap)=>{
    setState(snap.docs.map(d=>({...d.data(), id:d.id})));
  }, (err)=>console.error("Firestore subscribe error ["+name+"]:", err));
}
function subscribeDoc(name, docId, setState, fallback){
  return onSnapshot(doc(db, name, docId), (snap)=>{
    setState(snap.exists() ? snap.data() : fallback);
  }, (err)=>console.error("Firestore doc subscribe error ["+name+"]:", err));
}
async function writeDoc(name, id, data){
  try{ await setDoc(doc(db, name, id), data); }catch(e){ console.error("Firestore write error:", e); }
}
async function patchDoc(name, id, data){
  try{ await updateDoc(doc(db, name, id), data); }catch(e){
    // doc may not exist yet - fall back to creating it
    try{ await setDoc(doc(db, name, id), data, {merge:true}); }catch(e2){ console.error("Firestore patch error:", e2); }
  }
}
async function removeDoc(name, id){
  try{ await deleteDoc(doc(db, name, id)); }catch(e){ console.error("Firestore delete error:", e); }
}

