function calcHPP(produk, bahanList) {
  return (produk.bahan||[]).reduce((s,b)=>{const x=bahanList.find(i=>i.id===b.id);return s+(x?x.harga*b.qty:0);},0);
}
function calcMargin(hj,hpp){return hj?((hj-hpp)/hj)*100:0;}
function suggestPrice(hpp,tm){return Math.ceil(hpp/(1-tm/100)/500)*500;}
function MarginBadge({margin,target}){
  const ok=margin>=target,warn=margin>=target*0.75;
  const c=ok?"#15803d":warn?"#d97706":"#dc2626",bg=ok?"#dcfce7":warn?"#fef3c7":"#fee2e2";
  return <span style={{background:bg,color:c,fontSize:11,fontWeight:700,padding:"2px 8px",borderRadius:99}}>{ok?"✓ ":"↓ "}{margin.toFixed(1)}%</span>;
}

// ─── LOGIN ────────────────────────────────────────────────────────────────────
function LoginScreen({onLogin,users,onForgotPassword}){
  const [u,setU]=useState("");const[p,setP]=useState("");const[err,setErr]=useState("");
  const [showPass,setShowPass]=useState(false);
  const [mode,setMode]=useState("login"); // "login" | "forgot"
  const [forgotUsername,setForgotUsername]=useState("");
  const [forgotMsg,setForgotMsg]=useState("");
  const [forgotLoading,setForgotLoading]=useState(false);

  function go(){const user=users.find(x=>x.username===u&&x.password===p);if(user){onLogin(user);}else setErr("Username atau password salah");}

  async function submitForgot(){
    if(!forgotUsername){ setForgotMsg("Isi username dulu."); return; }
    setForgotLoading(true); setForgotMsg("");
    const result = await onForgotPassword(forgotUsername);
    setForgotMsg(result.msg);
    setForgotLoading(false);
  }

  return(
    <div style={{minHeight:"100vh",background:"#4A2C2A",display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div style={{background:"#fff",borderRadius:20,padding:32,width:"100%",maxWidth:360,boxShadow:"0 20px 60px rgba(0,0,0,0.3)"}}>
        <div style={{textAlign:"center",marginBottom:28}}>
          <img src={LOGO_KOPINCANG} alt="Kopincang" style={{width:90,height:90,borderRadius:16,objectFit:"cover",margin:"0 auto 8px",display:"block",boxShadow:"0 4px 12px rgba(0,0,0,0.15)"}}/>
          <div style={{fontSize:22,fontWeight:900,color:"#4A2C2A"}}>Kopincang Kasir</div>
          <div style={{fontSize:12,color:"#888",marginTop:4}}>{mode==="login"?"Masuk untuk melanjutkan":"Reset Password"}</div>
        </div>

        {mode==="login"&&<>
          <div style={{marginBottom:12}}>
            <label style={{fontSize:11,fontWeight:600,color:"#8B5E3C",display:"block",marginBottom:4}}>Username</label>
            <input style={{border:"1.5px solid #e0d0c0",borderRadius:10,padding:"10px 12px",fontSize:14,width:"100%",boxSizing:"border-box",outline:"none"}}
              value={u} onChange={e=>setU(e.target.value)} placeholder="admin / kasir" onKeyDown={e=>e.key==="Enter"&&go()}/>
          </div>
          <div style={{marginBottom:8}}>
            <label style={{fontSize:11,fontWeight:600,color:"#8B5E3C",display:"block",marginBottom:4}}>Password</label>
            <div style={{position:"relative"}}>
              <input type={showPass?"text":"password"} style={{border:"1.5px solid #e0d0c0",borderRadius:10,padding:"10px 40px 10px 12px",fontSize:14,width:"100%",boxSizing:"border-box",outline:"none"}}
                value={p} onChange={e=>setP(e.target.value)} placeholder="••••••••" onKeyDown={e=>e.key==="Enter"&&go()}/>
              <button type="button" onClick={()=>setShowPass(s=>!s)} style={{position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",border:"none",background:"none",cursor:"pointer",color:"#bbb"}}>
                {showPass?<EyeOff size={17}/>:<Eye size={17}/>}
              </button>
            </div>
          </div>
          <div style={{textAlign:"right",marginBottom:16}}>
            <button type="button" onClick={()=>{setMode("forgot");setErr("");setForgotMsg("");}} style={{border:"none",background:"none",color:"#8B5E3C",fontSize:11,fontWeight:600,cursor:"pointer",textDecoration:"underline"}}>Lupa Password?</button>
          </div>
          {err&&<div style={{background:"#fee2e2",color:"#dc2626",fontSize:12,padding:"8px 12px",borderRadius:8,marginBottom:14,textAlign:"center"}}>{err}</div>}
          <button onClick={go} style={{width:"100%",background:"#6F4E37",color:"#fff",border:"none",borderRadius:12,padding:13,fontSize:15,fontWeight:800,cursor:"pointer"}}>Masuk</button>
        </>}

        {mode==="forgot"&&<>
          <div style={{marginBottom:14,fontSize:11,color:"#888",textAlign:"center"}}>
            Password baru akan dikirim ke email owner (Super Admin) yang sudah didaftarkan.
          </div>
          <div style={{marginBottom:16}}>
            <label style={{fontSize:11,fontWeight:600,color:"#8B5E3C",display:"block",marginBottom:4}}>Username</label>
            <input style={{border:"1.5px solid #e0d0c0",borderRadius:10,padding:"10px 12px",fontSize:14,width:"100%",boxSizing:"border-box",outline:"none"}}
              value={forgotUsername} onChange={e=>setForgotUsername(e.target.value)} placeholder="Username akun kamu"/>
          </div>
          {forgotMsg&&<div style={{background:"#FBF3E7",color:"#8B5E3C",fontSize:12,padding:"8px 12px",borderRadius:8,marginBottom:14,textAlign:"center"}}>{forgotMsg}</div>}
          <button onClick={submitForgot} disabled={forgotLoading} style={{width:"100%",background:"#6F4E37",color:"#fff",border:"none",borderRadius:12,padding:13,fontSize:15,fontWeight:800,cursor:"pointer",opacity:forgotLoading?0.6:1,marginBottom:10}}>
            {forgotLoading?"Mengirim...":"Kirim Password Baru"}
          </button>
          <button type="button" onClick={()=>{setMode("login");setForgotMsg("");}} style={{width:"100%",border:"none",background:"none",color:"#8B5E3C",fontSize:12,fontWeight:600,cursor:"pointer"}}>Kembali ke Login</button>
        </>}
      </div>
    </div>
  );
}

