  const [kasFilterStart,setKasFilterStart]=useState(new Date().toISOString().split("T")[0]); // dipakai Superadmin/Finance (range)
  const [kasFilterEnd,setKasFilterEnd]=useState(new Date().toISOString().split("T")[0]);
  const [kasViewAll,setKasViewAll]=useState(false);
  const [laporanStartDate,setLaporanStartDate]=useState(new Date().toISOString().split("T")[0]);
  const [laporanEndDate,setLaporanEndDate]=useState(new Date().toISOString().split("T")[0]);
  const [restockForm,setRestockForm]=useState({bahanId:"",qty:0,totalHarga:0});
  const [customProduk,setCustomProduk]=useState(null);
  const [customSelectedAddons,setCustomSelectedAddons]=useState([]);
  const [customQty,setCustomQty]=useState(1);
  const [addonModal,setAddonModal]=useState(null);
  const [editAddonForm,setEditAddonForm]=useState({id:"",nama:"",harga:0});
  const [btDevice,setBtDevice]=useState(null);
  const [btChar,setBtChar]=useState(null);
  const [btStatus,setBtStatus]=useState("disconnected"); // disconnected | connecting | connected | error

  function setTargetMargin(val){ setTargetMarginLocal(val); }

  // ── REALTIME SYNC: subscribe to Firestore, updates from ANY device appear instantly ──
  useEffect(()=>{
    const unsubBahan = subscribeCollection("kopincang_bahan", (list)=>{
      if(list.length===0 && !seeded){ INIT_BAHAN.forEach(b=>writeDoc("kopincang_bahan", b.id, b)); }
      else setBahanList(list);
    });
    const unsubProduk = subscribeCollection("kopincang_produk", (list)=>{
      if(list.length===0 && !seeded){ INIT_PRODUK.forEach(p=>writeDoc("kopincang_produk", p.id, p)); }
      else setProdukList(list);
    });
    const unsubAddon = subscribeCollection("kopincang_addon", (list)=>{
      if(list.length===0 && !seeded){ INIT_ADDON.forEach(a=>writeDoc("kopincang_addon", a.id, a)); }
      else setAddonList(list);
    });
    const unsubKategori = subscribeCollection("kopincang_kategori", (list)=>{
      if(list.length===0 && !seeded){
        [{id:"kat1",nama:"Kopi"},{id:"kat2",nama:"Kopi Susu"},{id:"kat3",nama:"Kopi Spesial"},{id:"kat4",nama:"Non-Kopi"}].forEach(k=>writeDoc("kopincang_kategori", k.id, k));
      } else setKategoriProdukList(list);
    });
    const unsubTrx = subscribeCollection("kopincang_transaksi", (list)=>{
      setTransaksi(list.map(t=>({...t,waktu:new Date(t.waktu)})).sort((a,b)=>b.waktu-a.waktu));
    });
    const unsubKas = subscribeCollection("kopincang_kas", (list)=>{ setKas(list); });
    const unsubHeld = subscribeCollection("kopincang_held_orders", (list)=>{
      setHeldOrders(list.sort((a,b)=>new Date(b.waktu)-new Date(a.waktu)));
    });
    const unsubSettings = subscribeDoc("kopincang_settings","main",(data)=>{
      if(data && typeof data.targetMargin==="number") setTargetMarginLocal(data.targetMargin);
      else writeDoc("kopincang_settings","main",{targetMargin:60});
    }, {targetMargin:60});
    setSeeded(true);
    setSyncStatus("online");
    return ()=>{ unsubBahan();unsubProduk();unsubAddon();unsubKategori();unsubTrx();unsubKas();unsubHeld();unsubSettings(); };
    // eslint-disable-next-line
  },[]);

  const cartTotal=cart.reduce((s,i)=>s+i.hargaJual*i.qty,0);
  const cartHPP=cart.reduce((s,i)=>s+i.hpp*i.qty,0);
  const [diskonMode,setDiskonMode]=useState("rp"); // "rp" | "persen"
  const [diskonInput,setDiskonInput]=useState(0);
  const [adminMode,setAdminMode]=useState("rp"); // "rp" | "persen"
  const [adminInput,setAdminInput]=useState(0);
  const diskon = diskonMode==="persen" ? Math.round(cartTotal*(diskonInput/100)) : diskonInput;
  const biayaAdmin = adminMode==="persen" ? Math.round(cartTotal*(adminInput/100)) : adminInput;
  const netTotal=Math.max(0,cartTotal-diskon-biayaAdmin);
  const cartLaba=netTotal-cartHPP;
  const now=new Date();
  const aktivTrx=transaksi.filter(t=>!t.cancelled);

  function filterByPeriod(list,dk="waktu"){
    return list.filter(t=>{
      const d=new Date(t[dk]);
      if(laporanPeriod==="custom"){
        const start=new Date(laporanStartDate+"T00:00:00");
        const end=new Date(laporanEndDate+"T23:59:59");
        return d>=start&&d<=end;
      }
      if(laporanPeriod==="hari") return d.toDateString()===now.toDateString();
      if(laporanPeriod==="minggu") return (now-d)/(86400000)<=7;
      return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();
    });
  }
  const filteredTrx=filterByPeriod(aktivTrx);
  const filteredKas=filterByPeriod(kas,"tanggal");
  const filteredTrxJual=filteredTrx.filter(t=>t.metode!=="Compliment");
  const filteredTrxCompliment=filteredTrx.filter(t=>t.metode==="Compliment");
  const totalPenjualan=filteredTrxJual.reduce((s,t)=>s+t.total,0);
  const totalLabaKotor=filteredTrxJual.reduce((s,t)=>s+t.laba,0);
  const totalNilaiCompliment=filteredTrxCompliment.reduce((s,t)=>s+t.total,0);
  const totalPemasukan=filteredKas.filter(k=>k.jenis==="pemasukan").reduce((s,k)=>s+k.jumlah,0);
  const totalPengeluaran=filteredKas.filter(k=>k.jenis==="pengeluaran").reduce((s,k)=>s+k.jumlah,0);
  const labaBersih=totalPenjualan+totalPemasukan-totalPengeluaran;
  const marginPeriod=totalPenjualan?(labaBersih/totalPenjualan)*100:0;

  const monthlyData=useMemo(()=>{
    const map={};
    function ensure(key,year,month){
      if(!map[key]) map[key]={year,month,penjualan:0,pemasukan:0,pengeluaran:0,trx:0,trxCompliment:0,nilaiCompliment:0};
      return map[key];
    }
    aktivTrx.forEach(t=>{
      const d=new Date(t.waktu),key=`${d.getFullYear()}-${d.getMonth()}`;
      const m=ensure(key,d.getFullYear(),d.getMonth());
      if(t.metode==="Compliment"){ m.trxCompliment+=1; m.nilaiCompliment+=t.total; }
      else { m.penjualan+=t.total; m.trx+=1; }
    });
    kas.forEach(k=>{
      const d=new Date(k.tanggal),key=`${d.getFullYear()}-${d.getMonth()}`;
      const m=ensure(key,d.getFullYear(),d.getMonth());
      if(k.jenis==="pemasukan") m.pemasukan+=k.jumlah; else m.pengeluaran+=k.jumlah;
    });
    return Object.values(map).map(m=>({...m,laba:m.penjualan+m.pemasukan-m.pengeluaran})).sort((a,b)=>b.year-a.year||b.month-a.month);
  },[aktivTrx,kas]);

  const produkPerforma=useMemo(()=>{
    const map={};
    filteredTrx.forEach(t=>t.items.forEach(item=>{
      if(!map[item.id]) map[item.id]={nama:item.nama,qty:0,total:0,laba:0};
      map[item.id].qty+=item.qty;map[item.id].total+=item.hargaJual*item.qty;
      map[item.id].laba+=(item.hargaJual-item.hpp)*item.qty;
    }));
    return Object.values(map).sort((a,b)=>b.qty-a.qty);
  },[filteredTrx]);

  const lowStok=bahanList.filter(b=>b.stok<=b.minStok);
