  // ── PRINTER BLUETOOTH (Web Bluetooth API - Chrome/Edge only, HTTPS/localhost) ──
  const BT_SERVICE_CANDIDATES = ["000018f0-0000-1000-8000-00805f9b34fb","0000ff00-0000-1000-8000-00805f9b34fb","49535343-fe7d-4ae5-8fa9-9fafd205e455"];
  async function connectBluetoothPrinter(){
    if(!navigator.bluetooth){ setBtStatus("error"); alert("Browser ini tidak mendukung Bluetooth. Gunakan Chrome/Edge di Android atau Desktop."); return; }
    try{
      setBtStatus("connecting");
      const device = await navigator.bluetooth.requestDevice({ acceptAllDevices:true, optionalServices:BT_SERVICE_CANDIDATES });
      const server = await device.gatt.connect();
      let foundChar=null;
      for(const svcId of BT_SERVICE_CANDIDATES){
        try{
          const svc = await server.getPrimaryService(svcId);
          const chars = await svc.getCharacteristics();
          foundChar = chars.find(c=>c.properties.write||c.properties.writeWithoutResponse) || chars[0];
          if(foundChar) break;
        }catch(e){ /* try next service */ }
      }
      if(!foundChar) throw new Error("Karakteristik printer tidak ditemukan");
      setBtDevice(device); setBtChar(foundChar); setBtStatus("connected");
      device.addEventListener("gattserverdisconnected", ()=>{ setBtStatus("disconnected"); setBtDevice(null); setBtChar(null); });
    }catch(e){
      console.error(e); setBtStatus("error");
      alert("Gagal konek ke printer: "+e.message+"\n\nPastikan printer sudah menyala dan dalam mode pairing.");
    }
  }
  async function printViaBluetooth(trx){
    if(!btChar){ alert("Printer belum terhubung. Hubungkan dulu di menu Pengaturan."); return; }
    try{
      const encoder = new TextEncoder();
      const tgl=new Date(trx.waktu).toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"});
      const ESC="\x1b", GS="\x1d";
      let text = ESC+"@"; // init
      text += ESC+"a"+"\x01"; // center align
      text += "KOPINCANG\n";
      text += ESC+"a"+"\x00"; // left align
      text += tgl+(trx.cancelled?" (DIBATALKAN)":"")+"\n";
      text += "--------------------------------\n";
      trx.items.forEach(i=>{ text += `${i.nama} x${i.qty}`.padEnd(22)+rp(i.hargaJual*i.qty).padStart(10)+"\n"; });
      text += "--------------------------------\n";
      text += "TOTAL".padEnd(22)+rp(trx.total).padStart(10)+"\n";
      text += "Metode".padEnd(22)+trx.metode.padStart(10)+"\n";
      text += "\n\nTerima kasih!\n\n\n";
      text += GS+"V"+"\x00"; // cut paper (if supported)
      const bytes = encoder.encode(text);
      const CHUNK=180;
      for(let i=0;i<bytes.length;i+=CHUNK){
        await btChar.writeValue(bytes.slice(i,i+CHUNK));
      }
    }catch(e){
      console.error(e); alert("Gagal mencetak: "+e.message);
    }
  }
